//! Gold: `dw-queue` is 1:1 with the live `harness/pipeline/store.py`.
//!
//! `tests/fixtures/gold/queue_battery_v1.json` was generated by
//! `scripts/gold_queue_battery.py` from the reference with the clock pinned;
//! this replays the same operations, with the same clock advances, through
//! the Rust port and compares table state.
//!
//! Two documented normalisations in the comparison: `payload`/
//! `page_label_map` hold JSON as text (the reference prints `{"p": 1}`, serde
//! prints `{"p":1}` — the bytes differ, the JSON does not), and
//! `budget_spend.day` is wall-clock in the reference (un-pinnable from
//! outside), so the comparison masks it.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    reason = "gold tests assert on their own fixtures"
)]

use std::collections::BTreeMap;
use std::path::PathBuf;
use std::rc::Rc;

use dw_queue::{Clock, ManualClock, NewJob, Queue, VerdictInput};

const T0: f64 = 1_700_000_000.0;

/// Adapter so the test can advance the clock the queue stamps with.
struct RcClock(Rc<ManualClock>);

impl Clock for RcClock {
    fn now(&self) -> f64 {
        self.0.now()
    }
    fn today(&self) -> String {
        self.0.today()
    }
}

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/queue_battery_v1.json")
}

fn fresh(name: &str) -> (Queue, Rc<ManualClock>) {
    let path = std::env::temp_dir().join(format!("dw-queue-gold-{}-{name}.db", std::process::id()));
    let _ = std::fs::remove_file(&path);
    let clock = Rc::new(ManualClock::new(T0, "2026-10-12"));
    let q = Queue::open_with_clock(&path, RcClock(clock.clone())).expect("queue opens");
    (q, clock)
}

fn new_job(kind: &str, corpus: &str) -> NewJob {
    NewJob {
        kind: kind.into(),
        corpus_key: corpus.into(),
        max_attempts: 3,
        ..NewJob::default()
    }
}

/// Parse-through normalisation: strings that are themselves JSON become the
/// parsed value; `budget_spend.day` is masked.
fn normalise(v: &serde_json::Value) -> serde_json::Value {
    match v {
        serde_json::Value::String(s) => {
            serde_json::from_str(s).unwrap_or_else(|_| serde_json::Value::String(s.clone()))
        }
        serde_json::Value::Array(a) => serde_json::Value::Array(a.iter().map(normalise).collect()),
        serde_json::Value::Object(o) => {
            let mut out = serde_json::Map::new();
            for (k, val) in o {
                if k == "day" {
                    out.insert(k.clone(), serde_json::Value::String("DAY".into()));
                } else {
                    out.insert(k.clone(), normalise(val));
                }
            }
            serde_json::Value::Object(out)
        }
        other => other.clone(),
    }
}

fn assert_state(name: &str, q: &Queue) {
    let gold: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap();
    let got = normalise(&q.dump_tables().unwrap());
    let want = normalise(&gold[name]);
    assert_eq!(got, want, "scenario {name} diverged from the reference");
}

#[test]
fn enqueue_claim_ack_matches_the_reference() {
    let (q, clock) = fresh("a");
    let mut a = new_job("substrate", "sha256:aaa");
    a.source_path = Some("/x/a.pdf".into());
    q.enqueue(&a).unwrap();
    let mut b = new_job("substrate", "sha256:bbb");
    b.budget_tier = Some("local-student".into());
    b.payload = Some(serde_json::json!({"p": 1}));
    q.enqueue(&b).unwrap();
    q.enqueue(&new_job("extract", "sha256:ccc")).unwrap();
    clock.advance(1.0);
    let claimed = q.claim("worker-1", &["substrate"], 10).unwrap();
    clock.advance(1.0);
    q.ack(
        claimed[0].id,
        "ext",
        "v1",
        r#"{"rows": 1}"#,
        None,
        None,
        "substrate",
    )
    .unwrap();
    q.ack(
        claimed[1].id,
        "ext",
        "v1",
        r#"{"rows": 2}"#,
        None,
        None,
        "substrate",
    )
    .unwrap();
    assert_state("enqueue_claim_ack", &q);
}

#[test]
fn fail_to_dead_matches_the_reference() {
    let (q, clock) = fresh("b");
    let mut d = new_job("substrate", "sha256:ddd");
    d.max_attempts = 2;
    q.enqueue(&d).unwrap();
    for _ in 0..3 {
        clock.advance(5.0);
        let got = q.claim("worker-2", &["substrate"], 5).unwrap();
        if let Some(job) = got.first() {
            q.fail(job.id, "boom").unwrap();
        }
    }
    assert_state("fail_to_dead", &q);
}

#[test]
fn visibility_reclaim_matches_the_reference() {
    let (q, clock) = fresh("c");
    q.enqueue(&new_job("substrate", "sha256:eee")).unwrap();
    clock.advance(1.0);
    let a = q.claim("worker-a", &["substrate"], 5).unwrap();
    assert_eq!(a.len(), 1);
    clock.advance(100.0);
    let b_early = q.claim("worker-b", &["substrate"], 5).unwrap();
    assert!(
        b_early.is_empty(),
        "the lease is still visible — B gets nothing"
    );
    clock.advance(4000.0);
    let b_late = q.claim("worker-b", &["substrate"], 5).unwrap();
    assert_eq!(
        b_late.len(),
        1,
        "visibility expired — the lease is reclaimed"
    );
    q.ack(b_late[0].id, "ext", "v1", "{}", None, None, "substrate")
        .unwrap();
    assert_state("visibility_reclaim", &q);
}

#[test]
fn ack_dedup_and_ledger_match_the_reference() {
    let (q, clock) = fresh("d");
    q.enqueue(&new_job("substrate", "sha256:fff")).unwrap();
    clock.advance(1.0);
    let got = q.claim("worker-3", &["substrate"], 5).unwrap();
    let first = q
        .ack(
            got[0].id,
            "ext",
            "v1",
            r#"{"n": 1}"#,
            None,
            None,
            "substrate",
        )
        .unwrap();
    q.ack(
        got[0].id,
        "ext",
        "v1",
        r#"{"n": 1}"#,
        None,
        None,
        "substrate",
    )
    .unwrap();
    q.record_verdicts(
        first,
        "judge",
        "j1",
        &[VerdictInput {
            claim_index: Some(0),
            severity: "P0".into(),
            verdict: "UNSUPPORTED".into(),
            reason_code: Some("value_not_in_quote".into()),
            evidence_quote: Some("q".into()),
            failure_class: Some("hallucination".into()),
        }],
        Some("ext"),
    )
    .unwrap();
    assert_state("ack_dedup_and_ledger", &q);
}

#[test]
fn budget_caps_match_the_reference() {
    let (q, _clock) = fresh("e");
    let mut caps = BTreeMap::new();
    caps.insert("frontier".to_string(), 2_i64);
    let (r1, _) = q.budget_check("frontier", &caps).unwrap();
    let (r2, _) = q.budget_check("frontier", &caps).unwrap();
    let (r3, _) = q.budget_check("frontier", &caps).unwrap();
    assert!(r1 && r2 && !r3, "the cap must stop at 2");
    assert_state("budget", &q);
}

/// Negative control — the semantics the queue exists for. Claim order is
/// the reference's `ORDER BY created_at DESC`: newest lease first (the
/// corpus-keyed dedup and the terminal sweep make the order safe).
#[test]
fn negative_control_queue_semantics() {
    let (q, clock) = fresh("f");
    let mut ids: Vec<i64> = Vec::new();
    for k in ["a", "b", "c"] {
        clock.advance(1.0);
        ids.push(
            q.enqueue(&new_job("substrate", &format!("sha256:{k}")))
                .unwrap(),
        );
    }
    let got = q.claim("w", &["substrate"], 10).unwrap();
    let got_ids: Vec<i64> = got.iter().map(|j| j.id).collect();
    let mut newest_first = ids.clone();
    newest_first.reverse();
    assert_eq!(
        got_ids, newest_first,
        "claim order is newest-first by created_at"
    );
    q.ack(ids[0], "e", "v", "{}", None, None, "substrate")
        .unwrap();
    let again = q.claim("w", &["substrate"], 10).unwrap();
    assert!(
        !again.iter().any(|j| j.id == ids[0]),
        "done is never re-claimed"
    );
    let mut hard = new_job("substrate", "sha256:hard");
    hard.max_attempts = 1;
    let hid = q.enqueue(&hard).unwrap();
    let got = q.claim("w", &["substrate"], 1).unwrap();
    q.fail(got[0].id, "x").unwrap();
    let again = q.claim("w", &["substrate"], 10).unwrap();
    assert!(!again.iter().any(|j| j.id == hid), "dead stays dead");
}
